In:  msg.payload = { kommun: {kod,namn,lan_kod,lan_namn}, ar, valtyp }
Ut:  msg.payload = { meta, geojson: FeatureCollection, uppsamlingsdistrikt }

Hämtar valdistriktens geometri + resultat för valt år från val.se, hämtar samma sak för jämförelsevalet (ar - 4), normaliserar och slår ihop dem. Kastar ett Error om varken geometri eller aktuellt resultat kunde hämtas (fångas av en Catch-nod i den anropande fliken).

func:
// ============================================================================
// Subflow "HamtaValdata" - enda funktionsnoden.
// In:  msg.payload = { kommun: {kod,namn,lan_kod,lan_namn}, ar, valtyp }
// Ut:  msg.payload = { meta, geojson: FeatureCollection, uppsamlingsdistrikt }
//
// Både resultat- och geometridelen är verifierade mot riktiga filer från
// val.se: Val_20220911_preliminar_1488_KF.zip (kommunval Trollhättan 2022)
// respektive valdistrikt-riket-2026.zip (samtliga valdistrikt i riket,
// SWEREF99 TM - konverteras till WGS84 av H.geoIndexForYear()).
// ============================================================================
const H = global.get("valHelpers");
const cfg = global.get("valConfig");

const { kommun, ar, valtyp } = msg.payload;
const isLive = cfg.liveYears.indexOf(ar) !== -1;
const ttl = isLive ? cfg.cacheTtlLiveMs : cfg.cacheTtlFinalMs;
const jamforAr = ar - cfg.jamforOffsetAr;
const varningar = [];

// ---------------------------------------------------------------------------
// 1. Hämta geometrin (valdistriktens utbredning) för kommunen.
// ---------------------------------------------------------------------------
let geoFeatures = [];
try {
    const geoIndex = await H.geoIndexForYear(ar);
    geoFeatures = geoIndex.featuresByKommun.get(kommun.kod) || [];
    if (geoIndex.faktisktAr !== ar) {
        varningar.push(
            "Ingen karta konfigurerad för " + ar + " än - visar distriktsgränserna från " +
            geoIndex.faktisktAr + " istället (kan skilja sig något om distrikt ändrats sedan dess)."
        );
    }
} catch (e) {
    varningar.push("Kunde inte hämta/tolka geometrifil: " + e.message);
}

// ---------------------------------------------------------------------------
// 2. Hämta och normalisera en resultat-zip från val.se för ett givet år.
//
// Zip:en innehåller (bekräftat exempel: kommunval Trollhättan 2022):
//   Val_..._rostfordelning_{kod}_{NIVA}.json  <- röster per VALDISTRIKT
//   Val_..._mandatfordelning_{kod}_{NIVA}.json <- mandat per KOMMUN/VALKRETS
//     (mandat finns alltså INTE per valdistrikt, bara aggregerat högre upp)
//
// rostfordelning.valdistrikt[] - ett objekt per valdistrikt/uppsamlingsdistrikt:
//   { namn, valdistriktstyp: "valdistrikt"|"uppsamlingsdistrikt",
//     valdistriktskod (8 siffror, eller 6 för uppsamlingsdistrikt),
//     kommunkod, lankod, kretskod (valkrets), antalRostberattigade,
//     valdeltagandeVallokal, rapporteringsTid,
//     rostfordelning: { rosterPaverkaMandat: { antalRoster, partiRoster: [
//         { partiforkortning, partibeteckning, partikod, fargkod, antalRoster, andelRoster }
//     ], rosterOvrigaPartier: { antalRoster, andelRoster } } } }
// ---------------------------------------------------------------------------
function samlaValdistriktposter(obj, ut, djup) {
    if (djup > 6 || obj === null || typeof obj !== "object") return;
    if (Array.isArray(obj)) {
        if (obj.length && obj[0] && typeof obj[0] === "object" && "valdistriktskod" in obj[0]) {
            ut.push(...obj);
            return;
        }
        for (const item of obj) samlaValdistriktposter(item, ut, djup + 1);
        return;
    }
    for (const key of Object.keys(obj)) samlaValdistriktposter(obj[key], ut, djup + 1);
}

async function hamtaOchNormaliseraResultat(forAr) {
    const status = cfg.liveYears.indexOf(forAr) !== -1 ? "p" : "s";
    const url = H.resultatUrl(forAr, valtyp, kommun, status);
    const zipBuf = await H.fetchBuffer(url, `resultat_${forAr}_${valtyp}_${kommun.kod}`, ttl);

    const zip = new AdmZip(zipBuf);
    const entries = zip.getEntries();
    const rostEntry = entries.find((e) => /rostfordelning.*\.json$/i.test(e.entryName));
    if (!rostEntry) {
        throw new Error(
            "Hittade ingen rostfordelning-*.json i " + url + ". Filer i arkivet: [" +
            entries.map((e) => e.entryName).join(", ") + "]"
        );
    }
    const raw = JSON.parse(rostEntry.getData().toString("utf8"));

    let lista = Array.isArray(raw.valdistrikt) ? raw.valdistrikt : null;
    if (!lista) {
        lista = [];
        samlaValdistriktposter(raw, lista, 0);
        if (lista.length === 0) {
            throw new Error(
                "Hittade ingen 'valdistrikt'-lista i " + rostEntry.entryName +
                ". Toppnivåfält: [" + Object.keys(raw).join(", ") + "]"
            );
        }
    }

    const byKod = new Map();
    for (const rec of lista) {
        const recKommunkod = String(rec.kommunkod || "").padStart(4, "0");
        if (recKommunkod !== kommun.kod) continue;

        const kod = String(rec.valdistriktskod);
        const rp = (rec.rostfordelning && rec.rostfordelning.rosterPaverkaMandat) || { partiRoster: [] };
        const roster = (rp.partiRoster || []).map((p) => ({
            parti: p.partiforkortning,
            partiNamn: p.partibeteckning,
            röster: p.antalRoster,
            andel: p.andelRoster,
            farg: p.fargkod || null
        }));
        if (rp.rosterOvrigaPartier && rp.rosterOvrigaPartier.antalRoster > 0) {
            roster.push({
                parti: "OVR",
                partiNamn: "Övriga partier",
                röster: rp.rosterOvrigaPartier.antalRoster,
                andel: rp.rosterOvrigaPartier.andelRoster,
                farg: null
            });
        }

        let ledandeParti = null;
        let bastAndel = -1;
        for (const p of roster) {
            if (p.andel > bastAndel) {
                bastAndel = p.andel;
                ledandeParti = p.parti;
            }
        }

        byKod.set(kod, {
            kod,
            namn: rec.namn,
            typ: rec.valdistriktstyp === "uppsamlingsdistrikt" ? "uppsamling" : "ordinarie",
            valdeltagande: rec.valdeltagandeVallokal ?? null,
            roster,
            ledandeParti
        });
    }

    return { byKod, senasteUppdateringstid: raw.senasteUppdateringstid || null };
}

// ---------------------------------------------------------------------------
// 3. Hämta nuvarande och (om möjligt) föregående jämförelseval.
// ---------------------------------------------------------------------------
let currentByKod = new Map();
let senasteUppdateringstid = null;
try {
    const r = await hamtaOchNormaliseraResultat(ar);
    currentByKod = r.byKod;
    senasteUppdateringstid = r.senasteUppdateringstid;
} catch (e) {
    varningar.push("Kunde inte hämta/tolka resultat för " + ar + ": " + e.message);
}

let prevByKod = new Map();
let harJamforelse = true;
try {
    const r = await hamtaOchNormaliseraResultat(jamforAr);
    prevByKod = r.byKod;
} catch (e) {
    harJamforelse = false;
    varningar.push("Kunde inte hämta jämförelseval " + jamforAr + ": " + e.message);
}

if (currentByKod.size === 0 && geoFeatures.length === 0) {
    // Inget att visa alls - eskalera till fel så anropande flöde kan svara 502.
    const err = new Error(varningar.join(" | ") || "Ingen data hittades.");
    throw err;
}

// ---------------------------------------------------------------------------
// 4. Bygg jämförelse per distrikt (nuvarande vs föregående val).
// ---------------------------------------------------------------------------
function byggJamforandeDistrikt(kod, curr) {
    const prev = prevByKod.get(kod);
    const jamforbar = harJamforelse && !!prev;

    const roster = curr.roster.map((p) => {
        const prevParti = prev ? prev.roster.find((pp) => pp.parti === p.parti) : null;
        return {
            parti: p.parti,
            partiNamn: p.partiNamn,
            röster: p.röster,
            andel: p.andel,
            farg: p.farg,
            andel_forra: prevParti ? prevParti.andel : null,
            forandring: prevParti ? Number((p.andel - prevParti.andel).toFixed(2)) : null
        };
    });

    return {
        kod: curr.kod,
        namn: curr.namn,
        typ: curr.typ,
        valdeltagande: curr.valdeltagande,
        valdeltagande_forra: prev ? prev.valdeltagande : null,
        roster,
        ledandeParti: curr.ledandeParti,
        ledandeParti_forra: prev ? prev.ledandeParti : null,
        partibyte: jamforbar ? prev.ledandeParti !== curr.ledandeParti : false,
        jamforbar
    };
}

// geoFeatures kommer redan normaliserade (properties.valdistriktskod) från
// H.geoIndexForYear(), se initConfig.js.
const geoByKod = new Map();
for (const f of geoFeatures) {
    geoByKod.set(f.properties.valdistriktskod, f);
}

const features = [];
const uppsamlingsdistrikt = [];

for (const [kod, curr] of currentByKod.entries()) {
    const properties = byggJamforandeDistrikt(kod, curr);
    const geoFeature = geoByKod.get(kod);
    if (geoFeature && curr.typ !== "uppsamling") {
        features.push({
            type: "Feature",
            geometry: geoFeature.geometry,
            properties
        });
    } else {
        uppsamlingsdistrikt.push(properties);
    }
}

// ---------------------------------------------------------------------------
// 5. Klart - bygg svaret.
// ---------------------------------------------------------------------------
msg.payload = {
    meta: {
        kommun,
        ar,
        valtyp,
        jamforAr: harJamforelse ? jamforAr : null,
        ar_live: isLive,
        senast_uppdaterad: senasteUppdateringstid || new Date().toISOString(),
        kalla: "val.se",
        varningar
    },
    geojson: {
        type: "FeatureCollection",
        features
    },
    uppsamlingsdistrikt
};

return msg;

// GET /val/api/kommuner -> lista över Sveriges 290 kommuner (kod, namn, län).
const H = global.get("valHelpers");
try {
    msg.payload = H.cachedReadJson("kommuner.json");
    msg.statusCode = 200;
} catch (e) {
    msg.statusCode = 500;
    msg.payload = { error: "Kunde inte läsa kommuner.json", detalj: e.message };
}
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
return msg;

// GET /val/api/valtyper -> riksdag / region / kommun
const H = global.get("valHelpers");
try {
    msg.payload = H.cachedReadJson("valtyper.json");
    msg.statusCode = 200;
} catch (e) {
    msg.statusCode = 500;
    msg.payload = { error: "Kunde inte läsa valtyper.json", detalj: e.message };
}
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
return msg;

// GET /val/api/partier -> färgsättning per parti (redigera gärna hex-koderna)
const H = global.get("valHelpers");
try {
    msg.payload = H.cachedReadJson("party-styles.json");
    msg.statusCode = 200;
} catch (e) {
    msg.statusCode = 500;
    msg.payload = { error: "Kunde inte läsa party-styles.json", detalj: e.message };
}
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
return msg;

// GET /val/api/ar -> valbara år, med status "live" (pollas i realtid) eller
// "final" (slutgiltigt facit, hämtas en gång och cachas).
const cfg = global.get("valConfig");

const live = cfg.liveYears.map((ar) => ({ ar, status: "live", namn: ar + " (pågående)" }));
const final = cfg.finalYears.map((ar) => ({ ar, status: "final", namn: String(ar) }));

const alla = live.concat(final).sort((a, b) => b.ar - a.ar);

msg.payload = alla;
msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
return msg;

// GET /val/api/valdistrikt?kommun=1281&ar=2022&valtyp=riksdag
// Två utgångar: 0 = ogiltig fråga (går direkt till http response),
//               1 = giltig fråga (går vidare till subflowet HamtaValdata).
const H = global.get("valHelpers");
const q = msg.req.query || {};

const kommunKod = String(q.kommun || "").trim();
const ar = parseInt(q.ar, 10);
const valtyp = String(q.valtyp || "").trim();
const giltigaValtyper = ["riksdag", "region", "kommun"];

let kommuner;
try {
    kommuner = H.cachedReadJson("kommuner.json");
} catch (e) {
    msg.statusCode = 500;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = { error: "Kunde inte läsa kommunlistan", detalj: e.message };
    return [msg, null];
}

const kommunInfo = kommuner.find((k) => k.kod === kommunKod);
const fel = [];
if (!kommunInfo) fel.push("okänd kommunkod: '" + kommunKod + "'");
if (!Number.isInteger(ar) || ar < 2002 || ar > 2100) fel.push("ogiltigt år: '" + q.ar + "'");
if (giltigaValtyper.indexOf(valtyp) === -1) {
    fel.push("ogiltig valtyp (måste vara riksdag/region/kommun): '" + valtyp + "'");
}

if (fel.length) {
    msg.statusCode = 400;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = { error: "Ogiltig förfrågan", detaljer: fel };
    return [msg, null];
}

msg.payload = { kommun: kommunInfo, ar, valtyp };
return [null, msg];

// Efter lyckat anrop till subflowet HamtaValdata: paketera som HTTP 200-svar.
msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
return msg;

// Fångar fel som kastas i subflowet HamtaValdata (t.ex. att val.se inte
// svarar, eller att ett fältnamn i normaliseringen inte hittas) och gör om
// dem till ett tydligt JSON-felsvar istället för att flödet kraschar tyst.
const err = msg.error || {};
node.warn("Fel vid hämtning av valdata: " + (err.message || JSON.stringify(err)));

msg.statusCode = 502;
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
msg.payload = {
    error: "Kunde inte hämta/tolka valresultat",
    detalj: err.message || String(err)
};
return msg;

// Statisk filserver för /val/* (Leaflet-kartan, JS, CSS).
// Kopplad från: http in "GET /val" och "GET /val/*"  ->  denna nod -> http response
// fs/path laddas via denna nods "Setup"-flik (redan ifyllt i flows-val.json),
// inte via require()/global.get(). cfg kommer från initConfig-noden.
const cfg = global.get("valConfig");
if (typeof fs === "undefined" || typeof path === "undefined" || !cfg) {
    msg.statusCode = 500;
    msg.payload = "Servern är inte klar (fs/path/valConfig saknas - se node-red/README.md).";
    return msg;
}

const MIME = {
    ".html": "text/html; charset=utf-8",
    ".js": "application/javascript; charset=utf-8",
    ".css": "text/css; charset=utf-8",
    ".json": "application/json; charset=utf-8",
    ".svg": "image/svg+xml",
    ".png": "image/png",
    ".ico": "image/x-icon",
    ".webmanifest": "application/manifest+json"
};

let reqPath = "";
if (msg.req.params && msg.req.params[0] !== undefined) {
    reqPath = msg.req.params[0];
} else if (msg.req.path) {
    reqPath = msg.req.path.replace(/^\/val\/?/, "");
}
if (reqPath === "" || reqPath.endsWith("/")) {
    reqPath += "index.html";
}

// Skydda mot path traversal ("../../etc/passwd" etc).
const resolved = path.resolve(cfg.webRoot, reqPath);
if (!resolved.startsWith(path.resolve(cfg.webRoot))) {
    msg.statusCode = 403;
    msg.payload = "Förbjuden sökväg";
    return msg;
}

try {
    const data = fs.readFileSync(resolved);
    const ext = path.extname(resolved).toLowerCase();
    msg.headers = { "Content-Type": MIME[ext] || "application/octet-stream" };
    msg.statusCode = 200;
    msg.payload = data;
} catch (e) {
    // Ge en så konkret felbeskrivning som möjligt - vilken absolut sökväg
    // det faktiskt letade efter, felkoden (ENOENT = filen finns inte där,
    // EACCES = behörighetsproblem), och gärna vad WEB_ROOT faktiskt
    // innehåller just nu, så det går att se direkt om cfg.webRoot bara
    // pekar fel eller om filerna inte kopierats dit än.
    let listing = "(kunde inte lista WEB_ROOT: " + cfg.webRoot + ")";
    try {
        listing = fs.readdirSync(cfg.webRoot).join(", ") || "(mappen är tom)";
    } catch (e2) {
        listing = "(kunde inte läsa mappen " + cfg.webRoot + ": " + e2.code + " " + e2.message + ")";
    }
    msg.statusCode = 404;
    msg.headers = { "Content-Type": "text/plain; charset=utf-8" };
    msg.payload =
        "Hittar inte filen. Sökte efter: " + resolved + " (" + (e.code || e.message) + ")\n" +
        "WEB_ROOT är satt till: " + cfg.webRoot + "\n" +
        "Innehåll i WEB_ROOT just nu: " + listing + "\n\n" +
        "Kontrollera att WEB_ROOT i noden \"Global konfiguration + hjälpfunktioner\" pekar på " +
        "mappen där du kopierade web/val/ (index.html, karta.html, css/, js/) från repot.";
}
return msg;

// ============================================================================
// INIT: körs en gång vid Deploy (triggas av injektionsnoden "Starta vid deploy")
// Sätter global konfiguration + delade hjälpfunktioner som resten av flödet
// (API-noderna, HamtaValdata-subflowet, polling-flödet) läser via global context.
// ============================================================================

// ---------------------------------------------------------------------------
// !!! ÄNDRA DESSA SÖKVÄGAR så de stämmer med var du lade filerna på servern !!!
// DATA_DIR   = mappen "node-red/data" från repot (kommuner.json, valtyper.json,
//              party-styles.json). Behöver bara vara LÄSBAR.
// WEB_ROOT   = mappen "web/val" från repot (index.html, karta.html, css, js).
//              Behöver bara vara läsbar.
// CACHE_DIR  = en SKRIVBAR katalog för nedladdad val.se-data (skapas
//              automatiskt om den saknas). Måste vara skrivbar för den
//              Node-RED-processen faktiskt kör som - i vissa miljöer (t.ex.
//              containrar) är /opt inte skrivbart och /tmp är enda alternativet;
//              byt då CACHE_DIR nedan. Ligger cachen under /tmp kan den
//              försvinna vid omstart - det är ofarligt, den byggs bara upp
//              på nytt vid nästa hämtning.
// ---------------------------------------------------------------------------
const DATA_DIR = "/opt/nodered/val/data";
const WEB_ROOT = "/opt/nodered/val/web/val";
const CACHE_DIR = "/tmp/val-cache";

// OBS: fs, path, AdmZip och proj4 kommer INTE från require() eller
// global.get() - de laddas via denna nods "Setup"-flik (redan förifyllt i
// flows-val.json, nodens "libs"-fält: fs, path, adm-zip, proj4). Det enda du
// behöver göra i settings.js är att sätta `functionExternalModules: true`
// samt `npm install adm-zip proj4` i Node-RED:s userDir (se node-red/README.md)
// - det är Node-RED:s inbyggda, avsedda mekanism för just detta och kräver
// ingen egen require()-kod i settings.js.
if (typeof fs === "undefined" || typeof path === "undefined" || typeof AdmZip === "undefined" || typeof proj4 === "undefined") {
    throw new Error(
        "Modulerna fs/path/AdmZip/proj4 är inte laddade. Kontrollera att " +
        "`functionExternalModules: true` är satt i din Node-RED settings.js, att " +
        "`npm install adm-zip proj4` körts i Node-RED:s userDir, att processen " +
        "startats om, samt att denna nods Setup-flik listar alla fyra. Se node-red/README.md."
    );
}

// Skapa cache-katalogen om den saknas.
try {
    fs.mkdirSync(CACHE_DIR, { recursive: true });
} catch (e) {
    node.warn("Kunde inte skapa cache-katalogen " + CACHE_DIR + ": " + e.message);
}

// ---------------------------------------------------------------------------
// URL:er för val.se:s resultatfiler. Verifierat mot en riktig fil (tack vare
// index.md5-listan på https://resultat.val.se/resultatfiler/val2022/index.md5
// och ett nedladdat exempel: Val_20220911_preliminar_1488_KF.zip):
//
//   https://resultat.val.se/resultatfiler/val{ar}/{p|s}/{niva}/
//       Val_{datum}_{preliminar|slutlig}_{kod}_{NIVA}.zip
//
// - {p|s}   = "p" (preliminär, uppdateras löpande på valnatten) eller
//             "s" (slutlig, det certifierade facit som används för 2018/2022)
// - {niva}  = "kf" (kommunfullmäktige, {kod} = 4-siffrig kommunkod),
//             "rf" (regionfullmäktige, {kod} = 2-siffrig länskod) eller
//             "rd" (riksdag, {kod} är alltid "00" - EN fil för hela landet)
// - {datum} = valdagens datum (ÅÅÅÅMMDD). Svenska allmänna val hålls alltid
//             andra söndagen i september, se electionDateSweden() nedan.
//
// Zip-filen innehåller två JSON-filer (+ .sha256-signaturer):
//   Val_..._rostfordelning_{kod}_{NIVA}.json  <- röster per VALDISTRIKT (denna använder vi)
//   Val_..._mandatfordelning_{kod}_{NIVA}.json <- mandat per KOMMUN/VALKRETS (ej per distrikt)
// Se valHelpers.resultatUrl() och subflowet HamtaValdata för hur de tolkas.
//
// ---------------------------------------------------------------------------
// Geometri (valdistriktens kartutbredning). Verifierad mot en riktig fil:
// valdistrikt-riket-2026.zip (från en download-länk på val.se, en
// CMS-genererad asset-URL - INTE ett förutsägbart mönster som resultat-URL:erna,
// så den kan inte byggas med en {ar}-mall. Lägg därför till en rad per år
// här allteftersom ni hittar/laddar ner filen för fler år.
//
// Filen innehåller EN geojson (SWEREF99 TM / EPSG:3006, konverteras till
// WGS84 av geoIndexForYear() nedan) med samtliga ~7000 valdistrikt i hela
// riket - samma geometri gäller för riksdags-, region- och kommunval, så en
// fil per år räcker för alla tre valtyper. Varje features properties har
// (bekräftat): Valdistriktskod, Valdistriktsnamn, Kommunkod, Kommun,
// Länskod, Län, Riksdagsvalkretskod/-namn, Kommunvalkretskod/-namn,
// Regionkod/-namn, Regionvalkretskod/-namn.
//
// Om ett valår saknas här används automatiskt närmast tillgängliga år
// istället (distriktsgränser ändras sällan mellan val) - detta flaggas då
// som en varning i svaret (meta.varningar) så det syns tydligt i kartan.
// ---------------------------------------------------------------------------
const geoUrls = {
    2026: "https://www.val.se/download/18.332cf48819bd61ac1513889/1785491689960/valdistrikt-riket-2026.zip"
};

// Svenska allmänna val hålls alltid andra söndagen i september. Returnerar
// datumet som "ÅÅÅÅMMDD", t.ex. 2022 -> "20220911", 2018 -> "20180909".
function electionDateSweden(ar) {
    const sep1 = new Date(Date.UTC(ar, 8, 1));
    const veckodag = sep1.getUTCDay(); // 0 = söndag
    const forstaSondagen = veckodag === 0 ? 1 : 8 - veckodag;
    const andraSondagen = forstaSondagen + 7;
    return String(ar) + "09" + String(andraSondagen).padStart(2, "0");
}

// Bygger URL till resultat-zip:en för ett givet år/valtyp/kommun.
// status: "p" (preliminär/levande år) eller "s" (slutlig/facit).
function resultatUrl(ar, valtyp, kommun, status) {
    const nivaKarta = {
        riksdag: { niva: "rd", NIVA: "RD", kod: "00" },
        region: { niva: "rf", NIVA: "RF", kod: kommunLanKod(kommun.kod) },
        kommun: { niva: "kf", NIVA: "KF", kod: kommun.kod }
    };
    const info = nivaKarta[valtyp];
    if (!info) throw new Error("Okänd valtyp: " + valtyp);
    const datum = electionDateSweden(ar);
    const statusNamn = status === "p" ? "preliminar" : "slutlig";
    return (
        "https://resultat.val.se/resultatfiler/val" + ar + "/" + status + "/" + info.niva +
        "/Val_" + datum + "_" + statusNamn + "_" + info.kod + "_" + info.NIVA + ".zip"
    );
}

// Vilka valår som är "levande" (pollas kontinuerligt via WS under valkvällen)
// resp. "slutgiltiga" (hämtas en gång och cachas permanent).
const liveYears = [2026];
const finalYears = [2022, 2018, 2014, 2010];

global.set("valConfig", {
    dataDir: DATA_DIR,
    webRoot: WEB_ROOT,
    cacheDir: CACHE_DIR,
    geoUrls: geoUrls,
    liveYears: liveYears,
    finalYears: finalYears,
    // Hur många år bakåt jämförelsen ska gå (val hålls vart 4:e år i Sverige).
    jamforOffsetAr: 4,
    // Hur ofta (ms) pollningsflödet kollar om det finns nya siffror för
    // levande prenumerationer.
    pollIntervalMs: 30000,
    // Hur länge (ms) en hämtad länsfil (geo/resultat) får cachas innan den
    // hämtas på nytt. Slutgiltiga år (2018, 2022, ...) cachas i praktiken
    // för alltid (30 dagar), levande år (2026) cachas bara en kort stund.
    cacheTtlLiveMs: 20000,
    cacheTtlFinalMs: 1000 * 60 * 60 * 24 * 30
});

// ---------------------------------------------------------------------------
// Delade hjälpfunktioner, tillgängliga i alla andra function-noder via:
//   const H = global.get("valHelpers");
// ---------------------------------------------------------------------------
const memoryJsonCache = new Map();

function cachedReadJson(fileName) {
    if (memoryJsonCache.has(fileName)) return memoryJsonCache.get(fileName);
    const full = path.join(DATA_DIR, fileName);
    const data = JSON.parse(fs.readFileSync(full, "utf8"));
    memoryJsonCache.set(fileName, data);
    return data;
}

function fillUrlTemplate(tpl, vars) {
    return tpl.replace(/\{(\w+)\}/g, (m, key) => {
        if (!(key in vars) || vars[key] === undefined || vars[key] === null) {
            throw new Error("Saknar värde för platshållare {" + key + "} i URL-mall: " + tpl);
        }
        return encodeURIComponent(vars[key]);
    });
}

function kommunLanKod(kommunKod) {
    return String(kommunKod).padStart(4, "0").slice(0, 2);
}

// Hämtar JSON över HTTP(S) med enkel filcache på disk. `cacheKey` blir
// filnamnet i cache-katalogen. `ttlMs` = hur länge cachen får användas.
async function fetchJson(url, cacheKey, ttlMs) {
    const cacheFile = path.join(CACHE_DIR, cacheKey.replace(/[^a-zA-Z0-9_.-]/g, "_") + ".json");
    try {
        const stat = fs.statSync(cacheFile);
        if (Date.now() - stat.mtimeMs < ttlMs) {
            return JSON.parse(fs.readFileSync(cacheFile, "utf8"));
        }
    } catch (e) {
        // ingen cache ännu, fortsätt till hämtning
    }

    if (typeof fetch !== "function") {
        throw new Error(
            "global fetch() saknas i denna Node-RED/Node.js-version. " +
            "Kör Node.js 18+ , eller byt ut fetchJson() mot http request-noder."
        );
    }

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 20000);
    let res;
    try {
        res = await fetch(url, { signal: controller.signal, headers: { "User-Agent": "val-karta-nodered/1.0" } });
    } catch (e) {
        throw new Error("Kunde inte nå " + url + ": " + e.message);
    } finally {
        clearTimeout(timeout);
    }
    if (!res.ok) {
        throw new Error("HTTP " + res.status + " från " + url);
    }
    const json = await res.json();
    try {
        fs.writeFileSync(cacheFile, JSON.stringify(json));
    } catch (e) {
        node.warn("Kunde inte skriva cache " + cacheFile + ": " + e.message);
    }
    return json;
}

// Som fetchJson, men för binärt innehåll (zip-arkiven från val.se). Returnerar
// en Buffer istället för tolkad JSON.
async function fetchBuffer(url, cacheKey, ttlMs) {
    const cacheFile = path.join(CACHE_DIR, cacheKey.replace(/[^a-zA-Z0-9_.-]/g, "_") + ".zip");
    try {
        const stat = fs.statSync(cacheFile);
        if (Date.now() - stat.mtimeMs < ttlMs) {
            return fs.readFileSync(cacheFile);
        }
    } catch (e) {
        // ingen cache ännu, fortsätt till hämtning
    }

    if (typeof fetch !== "function") {
        throw new Error(
            "global fetch() saknas i denna Node-RED/Node.js-version. " +
            "Kör Node.js 18+ , eller byt ut fetchBuffer() mot http request-noder."
        );
    }

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 30000);
    let res;
    try {
        res = await fetch(url, { signal: controller.signal, headers: { "User-Agent": "val-karta-nodered/1.0" } });
    } catch (e) {
        throw new Error("Kunde inte nå " + url + ": " + e.message);
    } finally {
        clearTimeout(timeout);
    }
    if (!res.ok) {
        throw new Error("HTTP " + res.status + " från " + url);
    }
    const buf = Buffer.from(await res.arrayBuffer());
    try {
        fs.writeFileSync(cacheFile, buf);
    } catch (e) {
        node.warn("Kunde inte skriva cache " + cacheFile + ": " + e.message);
    }
    return buf;
}

// Hämtar en zip (via fetchBuffer, filcachad) och JSON.parsar en fil ur den.
// entryRegex väljer vilken fil om arkivet innehåller fler än en.
async function fetchZipJson(url, cacheKey, ttlMs, entryRegex) {
    const buf = await fetchBuffer(url, cacheKey, ttlMs);
    const zip = new AdmZip(buf);
    const entries = zip.getEntries();
    const entry = entryRegex ? entries.find((e) => entryRegex.test(e.entryName)) : entries[0];
    if (!entry) {
        throw new Error(
            "Hittade ingen matchande fil i zip-arkivet " + url + ". Filer: [" +
            entries.map((e) => e.entryName).join(", ") + "]"
        );
    }
    return JSON.parse(entry.getData().toString("utf8"));
}

// ---------------------------------------------------------------------------
// Geometri: hämta, konvertera (SWEREF99 TM -> WGS84) och gruppera per
// kommun. Resultatet cachas i minnet (geoIndexCache) för hela Node-RED-
// processens livstid, per år - filen är ~100 MB uppacklad och behöver bara
// tolkas/omprojiceras EN gång, inte vid varje enskild förfrågan.
// ---------------------------------------------------------------------------
proj4.defs(
    "EPSG:3006",
    "+proj=tmerc +lat_0=0 +lon_0=15 +k=0.9996 +x_0=500000 +y_0=0 +ellps=GRS80 " +
    "+towgs84=0,0,0,0,0,0,0 +units=m +no_defs +type=crs"
);

function transformCoords(coords) {
    if (typeof coords[0] === "number") {
        return proj4("EPSG:3006", "EPSG:4326", coords);
    }
    return coords.map(transformCoords);
}

const geoIndexCache = new Map(); // faktisktAr -> Map<kommunkod, feature[]>

async function geoIndexForYear(ar) {
    let faktisktAr = ar;
    if (!geoUrls[faktisktAr]) {
        const tillgangliga = Object.keys(geoUrls)
            .map(Number)
            .sort((a, b) => b - a);
        if (tillgangliga.length === 0) {
            throw new Error("Ingen geodata-URL konfigurerad (geoUrls är tom i 'Global konfiguration + hjälpfunktioner').");
        }
        faktisktAr = tillgangliga[0];
    }

    if (!geoIndexCache.has(faktisktAr)) {
        // Engångskostnad per år: ~100 MB geojson, ~6300 distrikt i hela riket
        // att läsa in och omprojicera. Tar ~15 sekunder första gången - efter
        // det cachas resultatet i minnet så länge Node-RED-processen lever.
        node.warn("Bygger geometriindex för " + faktisktAr + " (engångskostnad, tar ca 15 sekunder)...");
        const url = geoUrls[faktisktAr];
        const raw = await fetchZipJson(url, `geo_${faktisktAr}`, 1000 * 60 * 60 * 24 * 30, /\.geojson$/i);

        const featuresByKommun = new Map();
        for (const f of raw.features || []) {
            const kkod = String((f.properties && f.properties.Kommunkod) || "").padStart(4, "0");
            if (!kkod || kkod === "0000") continue;
            const nyFeature = {
                type: "Feature",
                geometry: {
                    type: f.geometry.type,
                    coordinates: transformCoords(f.geometry.coordinates)
                },
                properties: {
                    valdistriktskod: String(f.properties.Valdistriktskod),
                    namn: f.properties.Valdistriktsnamn
                }
            };
            if (!featuresByKommun.has(kkod)) featuresByKommun.set(kkod, []);
            featuresByKommun.get(kkod).push(nyFeature);
        }
        geoIndexCache.set(faktisktAr, featuresByKommun);
    }

    return { featuresByKommun: geoIndexCache.get(faktisktAr), faktisktAr };
}

// Letar efter första matchande fältet i `obj` bland `candidates` (skiftlägesokänsligt).
// Kastar ett tydligt fel som listar de FAKTISKA nycklarna i objektet om inget
// hittas och `required` är sant — det gör det snabbt att lägga till rätt
// fältnamn när ni har verifierat den riktiga val.se-strukturen.
function pickField(obj, candidates, opts) {
    opts = opts || {};
    const keys = Object.keys(obj || {});
    const lowerMap = {};
    keys.forEach((k) => (lowerMap[k.toLowerCase()] = k));
    for (const c of candidates) {
        if (obj && Object.prototype.hasOwnProperty.call(obj, c)) return obj[c];
        const hit = lowerMap[c.toLowerCase()];
        if (hit !== undefined) return obj[hit];
    }
    if (opts.required) {
        throw new Error(
            "Hittade inget av fälten [" + candidates.join(", ") + "] (" + (opts.label || "okänt fält") +
            "). Faktiska fält i objektet: [" + keys.join(", ") + "]. " +
            "Lägg till rätt fältnamn i pickField-anropet i funktionsnoden."
        );
    }
    return opts.default;
}

global.set("valHelpers", {
    cachedReadJson,
    fillUrlTemplate,
    kommunLanKod,
    fetchJson,
    fetchBuffer,
    fetchZipJson,
    electionDateSweden,
    resultatUrl,
    geoIndexForYear,
    pickField
});

node.warn("val-karta: konfiguration och hjälpfunktioner initierade.");
return null;

// websocket in (/val/ws) -> denna nod. Hanterar prenumerationer.
// Klienten (web/val/js/karta.js) skickar:
//   {"type":"subscribe","kommun":"1281","ar":2022,"valtyp":"riksdag"}
// och skickar om samma meddelande var ~20:e sekund som "heartbeat" så att
// vi vet att fliken fortfarande är öppen (annars städas prenumerationen bort
// automatiskt av buildPollList efter 90 sekunders tystnad).
let data;
try {
    data = JSON.parse(msg.payload);
} catch (e) {
    node.warn("Ogiltigt WS-meddelande (inte JSON): " + msg.payload);
    return null;
}

const sessionId = msg._session && msg._session.id;
if (!sessionId) return null;

const subs = flow.get("wsSubs") || {};

if (data.type === "subscribe") {
    subs[sessionId] = {
        kommun: String(data.kommun),
        ar: parseInt(data.ar, 10),
        valtyp: String(data.valtyp),
        lastSeen: Date.now()
    };
    flow.set("wsSubs", subs);
} else if (data.type === "unsubscribe") {
    delete subs[sessionId];
    flow.set("wsSubs", subs);
}

node.status({ fill: "green", shape: "dot", text: Object.keys(subs).length + " prenumeranter" });
return null;

// Injiceras var `valConfig.pollIntervalMs` ms. Städar bort inaktiva
// WS-prenumerationer och bygger en lista med unika {kommun,ar,valtyp} som
// ska pollas mot val.se just nu (bara "levande" valår, se valConfig.liveYears).
// Ett utgående meddelande per kombination skickas vidare till subflowet
// HamtaValdata (kopplat direkt på denna nods enda utgång).
const cfg = global.get("valConfig");
const H = global.get("valHelpers");
const STALE_MS = 90000;
const now = Date.now();

const subs = flow.get("wsSubs") || {};
let ändrat = false;
for (const sid of Object.keys(subs)) {
    if (!subs[sid].lastSeen || now - subs[sid].lastSeen > STALE_MS) {
        delete subs[sid];
        ändrat = true;
    }
}
if (ändrat) flow.set("wsSubs", subs);

const unika = new Map();
for (const s of Object.values(subs)) {
    if (cfg.liveYears.indexOf(s.ar) === -1) continue; // slutgiltiga år pollas inte, bara skickas en gång via REST
    const key = s.kommun + "|" + s.ar + "|" + s.valtyp;
    if (!unika.has(key)) unika.set(key, { kommun: s.kommun, ar: s.ar, valtyp: s.valtyp });
}

node.status({ fill: "blue", shape: "dot", text: unika.size + " kombinationer pollas" });

if (unika.size === 0) return null;

let kommuner;
try {
    kommuner = H.cachedReadJson("kommuner.json");
} catch (e) {
    node.warn("buildPollList: kunde inte läsa kommuner.json: " + e.message);
    return null;
}

const meddelanden = [];
for (const combo of unika.values()) {
    const kommunInfo = kommuner.find((k) => k.kod === combo.kommun);
    if (!kommunInfo) continue;
    meddelanden.push({ payload: { kommun: kommunInfo, ar: combo.ar, valtyp: combo.valtyp } });
}

if (meddelanden.length === 0) return null;
return [meddelanden];

// Tar emot ett färskt resultat från subflowet HamtaValdata (en gång per
// {kommun,ar,valtyp}-kombination som pollas), jämför mot senast utskickade
// version och skickar bara ut det som faktiskt ändrats till de klienter som
// prenumererar på just den kombinationen. Kopplad till: websocket out (/val/ws).
const { meta, geojson, uppsamlingsdistrikt } = msg.payload;
const key = meta.kommun.kod + "|" + meta.ar + "|" + meta.valtyp;
const snapshotKey = "lastBroadcast_" + key;

const previous = global.get(snapshotKey) || {};
const nyaSnapshot = {};

function harAndrats(kod, properties) {
    const serialized = JSON.stringify(properties);
    nyaSnapshot[kod] = serialized;
    return previous[kod] !== serialized;
}

const distriktAndrade = [];
for (const f of geojson.features) {
    if (harAndrats(f.properties.kod, f.properties)) distriktAndrade.push(f.properties);
}
const uppsamlingAndrade = [];
for (const u of uppsamlingsdistrikt) {
    if (harAndrats(u.kod, u)) uppsamlingAndrade.push(u);
}

global.set(snapshotKey, nyaSnapshot);

const subs = flow.get("wsSubs") || {};
const targetSessions = Object.keys(subs).filter((sid) => {
    const s = subs[sid];
    return s.kommun === meta.kommun.kod && s.ar === meta.ar && s.valtyp === meta.valtyp;
});

if (targetSessions.length === 0) return null;

const harAndringar = distriktAndrade.length > 0 || uppsamlingAndrade.length > 0;
const payload = JSON.stringify({
    type: harAndringar ? "update" : "status",
    kommun: meta.kommun.kod,
    ar: meta.ar,
    valtyp: meta.valtyp,
    ar_live: meta.ar_live,
    senast_uppdaterad: meta.senast_uppdaterad,
    varningar: meta.varningar,
    distrikt: distriktAndrade,
    uppsamlingsdistrikt: uppsamlingAndrade
});

const utgaende = targetSessions.map((sid) => ({
    payload,
    _session: { type: "websocket", id: sid }
}));

return [utgaende];

// Catch-nod för pollningsflödet: ett fel här (t.ex. val.se nere en kort
// stund) ska aldrig krascha hela realtidsflödet - bara loggas. Nästa
// pollningscykel försöker automatiskt igen.
const err = msg.error || {};
node.warn("Pollningsfel (ignoreras, försöker igen nästa cykel): " + (err.message || JSON.stringify(err)));
return null;
